content:
Below is an idiomatic Pulumi TypeScript `ComponentResource` that wraps:

- **S3 bucket** with:
  - versioning
  - server-side encryption
  - public access blocked
- **RDS PostgreSQL** with:
  - deletion protection
  - backup retention
  - not publicly accessible
- **IAM role for service accounts** using **EKS OIDC trust**

It supports **dev/prod** via **Pulumi stack config**.

---

## `infra/appPlatform.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppPlatformArgs {
  appName: string;
  environment: string;

  // Networking for RDS
  vpcId: pulumi.Input<string>;
  privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;
  allowedSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

  // EKS OIDC for IRSA
  oidcProviderArn: pulumi.Input<string>;
  oidcProviderUrl: pulumi.Input<string>; // e.g. https://oidc.eks.us-east-1.amazonaws.com/id/XXXX
  kubernetesNamespace: pulumi.Input<string>;
  serviceAccountName: pulumi.Input<string>;

  // DB settings
  dbName: pulumi.Input<string>;
  dbUsername: pulumi.Input<string>;
  dbPassword: pulumi.Input<string>;
  dbInstanceClass: pulumi.Input<string>;
  dbAllocatedStorage?: pulumi.Input<number>;
  dbMultiAz?: pulumi.Input<boolean>;
  dbStorageEncrypted?: pulumi.Input<boolean>;
  backupRetentionPeriod?: pulumi.Input<number>;

  // Bucket
  replicationEnabled?: pulumi.Input<boolean>;
  replicationDestinationBucketArn?: pulumi.Input<string>;

  tags?: Record<string, pulumi.Input<string>>;
}

export class AppPlatform extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.BucketV2;
  public readonly dbInstance: aws.rds.Instance;
  public readonly serviceAccountRole: aws.iam.Role;
  public readonly dbSecurityGroup: aws.ec2.SecurityGroup;
  public readonly dbSubnetGroup: aws.rds.SubnetGroup;
  public readonly dbConnectionString: pulumi.Output<string>;

  constructor(name: string, args: AppPlatformArgs, opts?: pulumi.ComponentResourceOptions) {
    super("examples:infra:AppPlatform", name, {}, opts);

    const tags = {
      app: args.appName,
      environment: args.environment,
      managedBy: "pulumi",
      ...args.tags,
    };

    //
    // S3 Bucket
    //
    this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
      tags,
    }, { parent: this });

    new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
      bucket: this.bucket.id,
      versioningConfiguration: {
        status: "Enabled",
      },
    }, { parent: this });

    new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
      bucket: this.bucket.id,
      rules: [
        {
          applyServerSideEncryptionByDefault: {
            sseAlgorithm: "AES256",
          },
        },
      ],
    }, { parent: this });

    new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
      bucket: this.bucket.id,
      blockPublicAcls: true,
      blockPublicPolicy: true,
      ignorePublicAcls: true,
      restrictPublicBuckets: true,
    }, { parent: this });

    // Optional replication for prod if configured
    if (args.replicationEnabled && args.replicationDestinationBucketArn) {
      const replicationRole = new aws.iam.Role(`${name}-bucket-repl-role`, {
        assumeRolePolicy: aws.iam.assumeRolePolicyForPrincipal({
          Service: "s3.amazonaws.com",
        }),
        tags,
      }, { parent: this });

      new aws.iam.RolePolicy(`${name}-bucket-repl-policy`, {
        role: replicationRole.id,
        policy: pulumi.all([this.bucket.arn, args.replicationDestinationBucketArn]).apply(
          ([sourceArn, destArn]) =>
            JSON.stringify({
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "s3:GetReplicationConfiguration",
                    "s3:ListBucket",
                  ],
                  Resource: [sourceArn],
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:GetObjectVersionForReplication",
                    "s3:GetObjectVersionAcl",
                    "s3:GetObjectVersionTagging",
                  ],
                  Resource: [`${sourceArn}/*`],
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:ReplicateObject",
                    "s3:ReplicateDelete",
                    "s3:ReplicateTags",
                    "s3:ObjectOwnerOverrideToBucketOwner",
                  ],
                  Resource: [`${destArn}/*`],
                },
              ],
            }),
        ),
      }, { parent: this });

      new aws.s3.BucketReplicationConfig(`${name}-bucket-repl`, {
        bucket: this.bucket.id,
        role: replicationRole.arn,
        rules: [
          {
            id: "replicate-all",
            status: "Enabled",
            destination: {
              bucket: args.replicationDestinationBucketArn,
            },
          },
        ],
      }, { parent: this });
    }

    //
    // Security group + subnet group for RDS
    //
    this.dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
      vpcId: args.vpcId,
      description: `RDS access for ${name}`,
      ingress: [
        {
          protocol: "tcp",
          fromPort: 5432,
          toPort: 5432,
          securityGroups: args.allowedSecurityGroupIds,
          description: "PostgreSQL from application security groups",
        },
      ],
      egress: [
        {
          protocol: "-1",
          fromPort: 0,
          toPort: 0,
          cidrBlocks: ["0.0.0.0/0"],
          description: "Allow outbound",
        },
      ],
      tags,
    }, { parent: this });

    this.dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
      subnetIds: args.privateSubnetIds,
      tags,
    }, { parent: this });

    //
    // RDS PostgreSQL
    //
    this.dbInstance = new aws.rds.Instance(`${name}-postgres`, {
      engine: "postgres",
      engineVersion: "15.7",
      instanceClass: args.dbInstanceClass,
      allocatedStorage: args.dbAllocatedStorage ?? 20,
      dbSubnetGroupName: this.dbSubnetGroup.name,
      vpcSecurityGroupIds: [this.dbSecurityGroup.id],
      dbName: args.dbName,
      username: args.dbUsername,
      password: args.dbPassword,
      port: 5432,

      publiclyAccessible: false,
      deletionProtection: true,
      backupRetentionPeriod: args.backupRetentionPeriod ?? 7,
      skipFinalSnapshot: false,
      finalSnapshotIdentifier: `${name}-${args.environment}-final-snapshot`,

      multiAz: args.dbMultiAz ?? false,
      storageEncrypted: args.dbStorageEncrypted ?? true,

      applyImmediately: false,
      autoMinorVersionUpgrade: true,

      tags,
    }, { parent: this });

    //
    // IAM Role for Service Accounts (IRSA)
    //
    const oidcIssuer = pulumi.output(args.oidcProviderUrl).apply(url =>
      url.replace("https://", "")
    );

    this.serviceAccountRole = new aws.iam.Role(`${name}-sa-role`, {
      assumeRolePolicy: pulumi
        .all([
          args.oidcProviderArn,
          oidcIssuer,
          args.kubernetesNamespace,
          args.serviceAccountName,
        ])
        .apply(([providerArn, issuer, ns, sa]) =>
          JSON.stringify({
            Version: "2012-10-17",
            Statement: [
              {
                Effect: "Allow",
                Principal: {
                  Federated: providerArn,
                },
                Action: "sts:AssumeRoleWithWebIdentity",
                Condition: {
                  StringEquals: {
                    [`${issuer}:sub`]: `system:serviceaccount:${ns}:${sa}`,
                    [`${issuer}:aud`]: "sts.amazonaws.com",
                  },
                },
              },
            ],
          }),
        ),
      tags,
    }, { parent: this });

    // Least-privilege access to this app's bucket only
    new aws.iam.RolePolicy(`${name}-sa-bucket-policy`, {
      role: this.serviceAccountRole.id,
      policy: this.bucket.arn.apply(bucketArn =>
        JSON.stringify({
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Action: [
                "s3:ListBucket",
              ],
              Resource: [bucketArn],
            },
            {
              Effect: "Allow",
              Action: [
                "s3:GetObject",
                "s3:PutObject",
                "s3:DeleteObject",
              ],
              Resource: [`${bucketArn}/*`],
            },
          ],
        }),
      ),
    }, { parent: this });

    this.dbConnectionString = pulumi.secret(
      pulumi.interpolate`postgresql://${args.dbUsername}:${args.dbPassword}@${this.dbInstance.address}:5432/${args.dbName}`
    );

    this.registerOutputs({
      bucketName: this.bucket.bucket,
      bucketArn: this.bucket.arn,
      dbAddress: this.dbInstance.address,
      dbName: this.dbInstance.dbName,
      dbConnectionString: this.dbConnectionString,
      serviceAccountRoleArn: this.serviceAccountRole.arn,
      dbSecurityGroupId: this.dbSecurityGroup.id,
    });
  }
}
```

