## `index.ts`

This shows how to drive **dev/prod** from **stack config**.

```ts
import * as pulumi from "@pulumi/pulumi";
import { AppPlatform } from "./infra/appPlatform";

const stack = pulumi.getStack();
const cfg = new pulumi.Config();
const awsCfg = new pulumi.Config("aws");

// Common inputs from config
const appName = cfg.get("appName") || "webapp";
const environment = stack;

const platform = new AppPlatform(appName, {
  appName,
  environment,

  vpcId: cfg.require("vpcId"),
  privateSubnetIds: cfg.requireObject<string[]>("privateSubnetIds"),
  allowedSecurityGroupIds: cfg.requireObject<string[]>("allowedSecurityGroupIds"),

  oidcProviderArn: cfg.require("oidcProviderArn"),
  oidcProviderUrl: cfg.require("oidcProviderUrl"),
  kubernetesNamespace: cfg.get("kubernetesNamespace") || "default",
  serviceAccountName: cfg.get("serviceAccountName") || "webapp",

  dbName: cfg.get("dbName") || "appdb",
  dbUsername: cfg.get("dbUsername") || "appuser",
  dbPassword: cfg.requireSecret("dbPassword"),
  dbInstanceClass: cfg.require("dbInstanceClass"),
  dbAllocatedStorage: cfg.getNumber("dbAllocatedStorage") || 20,
  dbMultiAz: cfg.getBoolean("dbMultiAz") || false,
  dbStorageEncrypted: cfg.getBoolean("dbStorageEncrypted") ?? true,
  backupRetentionPeriod: cfg.getNumber("backupRetentionPeriod") || 7,

  replicationEnabled: cfg.getBoolean("replicationEnabled") || false,
  replicationDestinationBucketArn: cfg.get("replicationDestinationBucketArn"),

  tags: {
    region: awsCfg.require("region"),
    stack,
  },
});

export const bucketName = platform.bucket.bucket;
export const dbEndpoint = platform.dbInstance.address;
export const serviceAccountRoleArn = platform.serviceAccountRole.arn;
export const dbConnectionString = platform.dbConnectionString;
```

