### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1

  your-project:appName: webapp
  your-project:vpcId: vpc-9999999999
  your-project:privateSubnetIds:
    - subnet-xxx111
    - subnet-yyy222
    - subnet-zzz333
  your-project:allowedSecurityGroupIds:
    - sg-appprod123

  your-project:oidcProviderArn: arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE
  your-project:oidcProviderUrl: https://oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE
  your-project:kubernetesNamespace: app
  your-project:serviceAccountName: webapp

  your-project:dbName: appdb
  your-project:dbUsername: appuser
  your-project:dbInstanceClass: db.t3.medium
  your-project:dbAllocatedStorage: 100
  your-project:dbMultiAz: true
  your-project:dbStorageEncrypted: true
  your-project:backupRetentionPeriod: 14

  your-project:replicationEnabled: true
  your-project:replicationDestinationBucketArn: arn:aws:s3:::webapp-prod-replica-us-west-2
```

Set the prod DB password as a secret:

```bash
pulumi config set --stack prod --secret your-project:dbPassword 'strong-prod-password'
```

